// On-device replacement for server/src/db.ts (same exports used by the shared routes: DB, migrate, now, audit).
// It adapts SQLite WASM (a real SQLite file in the app's private OPFS storage) to the small node:sqlite surface the
// shared code uses: db.prepare(sql).get/all/run(...params), db.exec(sql), db.close(). Migrations are the SAME files as the
// server (server/migrations/*.sql), embedded at build time.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore virtual module generated by scripts/build-mobile.mjs
import MIGRATIONS from 'mh:migrations';

type Bind = null | number | bigint | string | Uint8Array;
interface WasmStmt { bind(v: Bind[]): WasmStmt; step(): boolean; get(o: object): Record<string, unknown>; finalize(): void }
export interface WasmDb { prepare(sql: string): WasmStmt; exec(sql: string | { sql: string; bind?: Bind[] }): unknown; changes(): number; selectValue(sql: string): unknown; close(): void; pointer: unknown }

const norm = (args: unknown[]): Bind[] => args.map((a) => (a === undefined ? null : typeof a === 'boolean' ? (a ? 1 : 0) : a instanceof ArrayBuffer ? new Uint8Array(a) : (a as Bind)));

/** node:sqlite-compatible facade (positional parameters only, which is all the shared code uses). */
export class LocalDB {
  constructor(public raw: WasmDb) {}
  prepare(sql: string) {
    const db = this.raw;
    const withStmt = <T>(args: unknown[], fn: (s: WasmStmt) => T): T => { const s = db.prepare(sql); try { if (args.length) s.bind(norm(args)); return fn(s); } finally { s.finalize(); } };
    return {
      get: (...args: unknown[]) => withStmt(args, (s) => (s.step() ? s.get({}) : undefined)),
      all: (...args: unknown[]) => withStmt(args, (s) => { const rows: Record<string, unknown>[] = []; while (s.step()) rows.push(s.get({})); return rows; }),
      run: (...args: unknown[]) => withStmt(args, (s) => { s.step(); return { changes: db.changes(), lastInsertRowid: Number(db.selectValue('SELECT last_insert_rowid()')) }; }),
    };
  }
  exec(sql: string) { this.raw.exec(sql); }
  close() { this.raw.close(); }
}
export type DB = LocalDB;

export function migrate(db: DB): string[] {
  db.exec('CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)');
  const applied = new Set((db.prepare('SELECT name FROM schema_migrations').all() as { name: string }[]).map((r) => r.name));
  const ran: string[] = [];
  for (const [name, sql] of (MIGRATIONS as [string, string][])) {
    if (applied.has(name)) continue;
    db.exec('BEGIN');
    try { db.exec(sql); db.prepare('INSERT INTO schema_migrations(name, applied_at) VALUES (?, ?)').run(name, new Date().toISOString()); db.exec('COMMIT'); ran.push(name); }
    catch (e) { db.exec('ROLLBACK'); throw e; }
  }
  return ran;
}
export const knownMigrations = (): string[] => (MIGRATIONS as [string, string][]).map(([n]) => n);
export const now = () => new Date().toISOString();
export function audit(db: DB, userId: number | null, action: string, entity: string, entityId: string | number, detail = '') {
  db.prepare('INSERT INTO audit_log(user_id, action, entity, entity_id, detail, at) VALUES (?,?,?,?,?,?)').run(userId, action, entity, String(entityId), detail, now());
}
/** Not used on the phone (the worker opens the database itself); present so imports resolve. */
export function openDb(): never { throw new Error('openDb is not available on the device; see mobile/src/worker.ts'); }
